    "imagenes": []
  },
  {
    "id": "q_la_ATP_2026_9357",
    "fuente": "ATP",
    "capitulo": 2,
    "capituloTitulo": "Equipment, Navigation, and Facilities",
    "seccion": "Safety of Flight Equipment",
    "materia": "operaciones",
    "text": "How long is flight deck voice recorder and flight recorder data kept, in the event of an accident or occurrence resulting in terminating the flight?",
    "options": [
      "60 days.",
      "90 days.",
      "30 days."
    ],
    "correctIndex": 0,
    "explanation": "In the event of an accident or occurrence requiring immediate notification to NTSB Part 830, and that results in the termination of a flight, any operator who has installed approved flight recorders and approved flight deck voice recorders shall keep the recorded information for at least 60 days. (PLT388, AA.I.G.K2) — 14 CFR §91.609",
    "cite": "ASA Airline Transport Pilot Test Prep 2025–2026 · Chapter 2 Equipment, Navigation, and Facilities · p. 2-14 · question 9357 · ALL",
    "sourceQuestionId": "9357",
    "sourceEdition": "2025–2026",
