  },
  {
    "id": "q_la_ATP_2026_9422",
    "fuente": "ATP",
    "capitulo": 2,
    "capituloTitulo": "Equipment, Navigation, and Facilities",
    "seccion": "Airport Lighting and Marking",
    "materia": "operaciones",
    "text": "Airport information signs, used to provide destination or information, have",
    "options": [
      "yellow inscriptions on a black background.",
      "white inscriptions on a black background.",
      "black inscriptions on a yellow background."
    ],
    "correctIndex": 2,
    "explanation": "Information signs have a yellow background with a black inscription. They are used to provide the pilot with information on such things as areas that cannot be seen from the control tower, applicable radio frequencies, and noise abatement procedures. (PLT141, AA.II.C.K3) — AIM ¶2-3-12",
    "cite": "ASA Airline Transport Pilot Test Prep 2025–2026 · Chapter 2 Equipment, Navigation, and Facilities · p. 2-45 · question 9422 · ATM, ATS, RTC",
    "sourceQuestionId": "9422",
    "sourceEdition": "2025–2026",
