    "imagenes": []
  },
  {
    "id": "q_la_ATP_2026_8247",
    "fuente": "ATP",
    "capitulo": 6,
    "capituloTitulo": "Flight Operations",
    "seccion": "Alternate Airport Planning",
    "materia": "operaciones",
    "text": "When the forecast weather conditions for a destination and alternate airport are considered marginal for a domestic air carrier’s operation, what specific action should the dispatcher or pilot-in-command take?",
    "options": [
      "List an airport where the forecast weather is not marginal as the alternate.",
      "Add 1 additional hour of fuel based on cruise power settings for the airplane in use.",
      "List at least one additional alternate airport."
    ],
    "correctIndex": 2,
    "explanation": "When weather conditions forecast for the destination and first alternate airport are marginal, at least one additional alternate must be designated. (PLT379, AA.I.G.K4) — 14 CFR §121.619",
    "cite": "ASA Airline Transport Pilot Test Prep 2025–2026 · Chapter 6 Flight Operations · p. 6-18 · question 8247 · ATM, ADX",
    "sourceQuestionId": "8247",
    "sourceEdition": "2025–2026",
