    "imagenes": []
  },
  {
    "id": "q_la_ATP_2026_8251",
    "fuente": "ATP",
    "capitulo": 6,
    "capituloTitulo": "Flight Operations",
    "seccion": "Alternate Airport Planning",
    "materia": "operaciones",
    "text": "When is a supplemental air carrier, operating under IFR, required to list an alternate airport for each destination airport within the 48 contiguous United States?",
    "options": [
      "When the forecast weather indicates the ceiling will be less than 1,000 feet and visibility less than 2 miles at the estimated time of arrival.",
      "On all flights, an alternate is required regardless of existing or forecast weather conditions at the destination.",
      "When the flight is scheduled for more than 6 hours en route."
    ],
    "correctIndex": 1,
    "explanation": "A supplemental air carrier must declare an alternate airport for all IFR operations. (PLT379, AA.I.G.K4) — 14 CFR §121.623",
    "cite": "ASA Airline Transport Pilot Test Prep 2025–2026 · Chapter 6 Flight Operations · p. 6-19 · question 8251 · ATM, ADX",
