    ]
  },
  {
    "id": "q_la_ATP_2026_9818",
    "fuente": "ATP",
    "capitulo": 6,
    "capituloTitulo": "Flight Operations",
    "seccion": "ATC Clearances",
    "materia": "operaciones",
    "text": "When should an aircraft depart if issued an EDCT?",
    "options": [
      "No earlier than 5 minutes before and no later than 5 minutes after the EDCT.",
      "No later than 5 minutes before and no earlier than 5 minutes after the EDCT.",
      "No earlier than 15 minutes before and no later than 15 minutes after the EDCT."
    ],
    "correctIndex": 0,
    "explanation": "The EDCT is the runway release time assigned to an aircraft included in traffic management programs. Aircraft are expected to depart no earlier than 5 minutes before, and no later than 5 minutes after the EDCT. (PLT080, AA.II.C.S3) — AIM ¶5-2-7",
    "cite": "ASA Airline Transport Pilot Test Prep 2025–2026 · Chapter 6 Flight Operations · p. 6-25 · question 9818 · ALL",
    "sourceQuestionId": "9818",
    "sourceEdition": "2025–2026",
