    "imagenes": []
  },
  {
    "id": "q_la_ATP_2026_9805_8",
    "fuente": "ATP",
    "capitulo": 7,
    "capituloTitulo": "Emergencies, Hazards, and Flight Physiology",
    "seccion": "Flight Physiology",
    "materia": "operaciones",
    "text": "In a multicrew environment, who is responsible for the tone, pace, and outcome of decisions made, and will be held accountable for all outcomes in air carrier flights?",
    "options": [
      "First officer.",
      "Air carrier.",
      "Captain."
    ],
    "correctIndex": 2,
    "explanation": "The captain is responsible for the tone, pace, and outcome of decisions, and will be held accountable for all outcomes of the flight. (PLT104, AA.I.E.K11) — AC 120-51",
    "cite": "ASA Airline Transport Pilot Test Prep 2025–2026 · Chapter 7 Emergencies, Hazards, and Flight Physiology · p. 7-17 · question 9805-8 · ALL",
    "sourceQuestionId": "9805-8",
