    ],
    "status": "publicada",
    "source": "import",
    "imagenes": []
  },
  {
    "id": "q_la_ATP_2026_9776",
    "fuente": "ATP",
    "capitulo": 8,
    "capituloTitulo": "Meteorology and Weather Services",
    "seccion": "Weather Systems",
    "materia": "operaciones",
    "text": "A jet stream is a narrow, shallow, meandering river of maximum winds extending around the globe in a wavelike pattern with speeds of",
    "options": [
      "50 knots or greater.",
      "71 knots or greater.",
      "100 knots or greater."
    ],
    "correctIndex": 0,
    "explanation": "The concentrated winds, by arbitrary definition, must be 50 knots or greater to be classified as a jet stream. (PLT302, AA.I.C.K3b) — FAA-H-8083-28",
    "cite": "ASA Airline Transport Pilot Test Prep 2025–2026 · Chapter 8 Meteorology and Weather Services · p. 8-11 · question 9776 · ALL",
    "sourceQuestionId": "9776",
    "sourceEdition": "2025–2026",
