  {
    "id": "q_la_ATP_2026_9835",
    "fuente": "ATP",
    "capitulo": 8,
    "capituloTitulo": "Meteorology and Weather Services",
    "seccion": "Thunderstorms",
    "materia": "operaciones",
    "text": "A steady state thunderstorm is associated with",
    "options": [
      "surface heating.",
      "weather systems.",
      "mature stage."
