  {
    "id": "q_la_ATP_2026_9180",
    "fuente": "ATP",
    "capitulo": 8,
    "capituloTitulo": "Meteorology and Weather Services",
    "seccion": "Frost and Ice",
    "materia": "operaciones",
    "text": "What condition is indicated when ice pellets are encountered during flight?",
