  },
  {
    "id": "q_la_ATP_2026_9226",
    "fuente": "ATP",
    "capitulo": 8,
    "capituloTitulo": "Meteorology and Weather Services",
    "seccion": "Turbulence",
    "materia": "operaciones",
    "text": "What is the lowest cloud in the stationary group associated with a mountain wave?",
    "options": [
