$questions$::jsonb;
 v_chapter1_images jsonb := $chapter1$[{"id":"q_la_ATP_2026_9618","imagenes":["atp_2026_figure-301-unit.svg"]},{"id":"q_la_ATP_2026_9636","imagenes":["atp_2026_legend-12-unit.svg"]},{"id":"q_la_ATP_2026_9638","imagenes":["atp_2026_figure-186-unit.svg","atp_2026_figure-187-unit.svg","atp_2026_figure-188-unit.svg","atp_2026_figure-188a-unit.svg"]},{"id":"q_la_ATP_2026_9668","imagenes":["atp_2026_legend-12-unit.svg","atp_2026_figure-185a-unit.svg"]}]$chapter1$::jsonb;
 v_expected jsonb := '{"2":213,"3":117,"6":216,"7":87,"8":230}'::jsonb;
 v_missing text;
 v_count integer;
 v_chapter text;
BEGIN
 IF jsonb_array_length(v_questions) <> 863 THEN RAISE EXCEPTION 'Expected 863 remaining ATP questions'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(v_questions) q WHERE
    q->>'fuente' <> 'ATP' OR q->>'capitulo' NOT IN ('2','3','6','7','8')
    OR q->>'sourceEdition' <> '2025–2026' OR q->>'status' <> 'publicada'
    OR jsonb_array_length(q->'options') <> 3 OR (q->>'correctIndex')::integer NOT BETWEEN 0 AND 2
    OR length(trim(q->>'explanation'))=0) THEN
   RAISE EXCEPTION 'Invalid or out-of-scope ATP source rows';
 END IF;
 IF (SELECT count(DISTINCT q->>'id') FROM jsonb_array_elements(v_questions) q) <> 863 THEN
   RAISE EXCEPTION 'Duplicate ATP IDs';
 END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(v_questions) q JOIN public.content c
   ON c.collection='questions' AND c.id=q->>'id'
   WHERE c.data->>'fuente' IS DISTINCT FROM 'ATP' OR c.data->>'capitulo' IS DISTINCT FROM q->>'capitulo') THEN
   RAISE EXCEPTION 'ATP ID collision with another bank or chapter';
 END IF;
 SELECT string_agg(file, ', ' ORDER BY file) INTO v_missing FROM (
   SELECT DISTINCT jsonb_array_elements_text(q->'imagenes') AS file
   FROM jsonb_array_elements(v_questions || v_chapter1_images) q
 ) required WHERE NOT EXISTS(SELECT 1 FROM storage.objects o WHERE o.bucket_id='atp-images' AND o.name=required.file);
 IF v_missing IS NOT NULL THEN RAISE EXCEPTION 'Upload missing ATP figures before replacing questions: %', v_missing; END IF;
 SELECT count(*) INTO v_count FROM public.content c JOIN jsonb_array_elements(v_chapter1_images) q ON c.id=q->>'id'
   WHERE c.collection='questions' AND c.data->>'fuente'='ATP' AND c.data->>'capitulo'='1'
   AND c.data->>'sourceEdition'='2025–2026' AND c.data->>'status'='publicada';
 IF v_count <> 4 THEN RAISE EXCEPTION 'Expected four existing chapter 1 figure questions'; END IF;

 UPDATE public.content c SET data=c.data || jsonb_build_object('status','oculta','replacedByEdition','2025–2026','updatedAt',now()::text),updated_at=now()
 WHERE c.collection='questions' AND c.data->>'fuente'='ATP' AND c.data->>'capitulo' IN ('2','3','6','7','8')
   AND c.data->>'status'='publicada'
   AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v_questions) q WHERE q->>'id'=c.id);

 INSERT INTO public.content(collection,id,data,updated_at)
 SELECT 'questions',q->>'id',q || jsonb_build_object('createdAt',COALESCE(existing.data->>'createdAt',now()::text),'updatedAt',now()::text),now()
 FROM jsonb_array_elements(v_questions) q LEFT JOIN public.content existing ON existing.collection='questions' AND existing.id=q->>'id'
 ON CONFLICT(collection,id) DO UPDATE SET data=EXCLUDED.data,updated_at=EXCLUDED.updated_at;

 UPDATE public.content c SET data=c.data || jsonb_build_object('imagenes',q->'imagenes','updatedAt',now()::text),updated_at=now()
 FROM jsonb_array_elements(v_chapter1_images) q
 WHERE c.collection='questions' AND c.id=q->>'id' AND c.data->>'fuente'='ATP' AND c.data->>'capitulo'='1' AND c.data->>'sourceEdition'='2025–2026';

 FOR v_chapter IN SELECT jsonb_object_keys(v_expected) LOOP
  SELECT count(*) INTO v_count FROM public.content c WHERE c.collection='questions' AND c.data->>'fuente'='ATP'
   AND c.data->>'capitulo'=v_chapter AND c.data->>'status'='publicada';
  IF v_count <> (v_expected->>v_chapter)::integer THEN RAISE EXCEPTION 'ATP chapter % replacement count failed: %',v_chapter,v_count; END IF;
 END LOOP;
 SELECT count(*) INTO v_count FROM public.content WHERE collection='questions' AND data->>'fuente'='ATP' AND data->>'capitulo'='1' AND data->>'status'='publicada';
 IF v_count <> 363 THEN RAISE EXCEPTION 'Chapter 1 question count changed'; END IF;
END;
$migration$;
